-- Check how many scans per zone and how many pointclouds exist
SELECT COUNT(*) FROM scans;
SELECT COUNT(*) FROM pointcloud;

-- Check if processing.equipref matches any scans.crewref or pointcloud.crewref
SELECT COUNT(DISTINCT p.equipref) FROM processing p;
SELECT COUNT(DISTINCT s.crewref) FROM scans s;

-- Check what the CASE WHEN returns when avg_efficiency_value is NULL
SELECT 
    CASE WHEN NULL < 0.5 THEN 'Bottleneck' ELSE 'Normal' END;

-- Check if using system_usage.Remain_Gb gives 122 groups
SELECT COUNT(*) FROM (
    SELECT p.flowsoft, p.flowstage
    FROM processing p
    GROUP BY p.flowsoft, p.flowstage
) sub;

SELECT COUNT(*) FROM (
    SELECT p.flowsoft, p.flowstage
    FROM processing p
    JOIN scans s ON p.zoneref = s.zoneref
    GROUP BY p.flowsoft, p.flowstage
) sub;
